-- Do not leave a visible answer-position pattern in the assessment.
-- Move every Spring Boot option out of its current position first, then
-- assign the final order without conflicting with the per-question position constraint.
update question_options
set position = position + 10
where question_id in (
  select id from questions
  where certification_id = '10000000-0000-0000-0000-000000000002'
);

update question_options
set position = case id
  when '30000000-0000-0000-0000-000000000101' then 3
  when '30000000-0000-0000-0000-000000000102' then 1
  when '30000000-0000-0000-0000-000000000103' then 2
  when '30000000-0000-0000-0000-000000000104' then 4

  when '30000000-0000-0000-0000-000000000111' then 2
  when '30000000-0000-0000-0000-000000000112' then 1
  when '30000000-0000-0000-0000-000000000113' then 3
  when '30000000-0000-0000-0000-000000000114' then 4

  when '30000000-0000-0000-0000-000000000121' then 4
  when '30000000-0000-0000-0000-000000000122' then 1
  when '30000000-0000-0000-0000-000000000123' then 2
  when '30000000-0000-0000-0000-000000000124' then 3

  when '30000000-0000-0000-0000-000000000131' then 1
  when '30000000-0000-0000-0000-000000000132' then 2
  when '30000000-0000-0000-0000-000000000133' then 3
  when '30000000-0000-0000-0000-000000000134' then 4

  when '30000000-0000-0000-0000-000000000141' then 2
  when '30000000-0000-0000-0000-000000000142' then 1
  when '30000000-0000-0000-0000-000000000143' then 3
  when '30000000-0000-0000-0000-000000000144' then 4

  when '30000000-0000-0000-0000-000000000151' then 3
  when '30000000-0000-0000-0000-000000000152' then 1
  when '30000000-0000-0000-0000-000000000153' then 2
  when '30000000-0000-0000-0000-000000000154' then 4

  when '30000000-0000-0000-0000-000000000161' then 4
  when '30000000-0000-0000-0000-000000000162' then 1
  when '30000000-0000-0000-0000-000000000163' then 2
  when '30000000-0000-0000-0000-000000000164' then 3

  when '30000000-0000-0000-0000-000000000171' then 1
  when '30000000-0000-0000-0000-000000000172' then 2
  when '30000000-0000-0000-0000-000000000173' then 3
  when '30000000-0000-0000-0000-000000000174' then 4

  when '30000000-0000-0000-0000-000000000181' then 2
  when '30000000-0000-0000-0000-000000000182' then 1
  when '30000000-0000-0000-0000-000000000183' then 3
  when '30000000-0000-0000-0000-000000000184' then 4

  when '30000000-0000-0000-0000-000000000191' then 3
  when '30000000-0000-0000-0000-000000000192' then 1
  when '30000000-0000-0000-0000-000000000193' then 2
  when '30000000-0000-0000-0000-000000000194' then 4
end
where id between '30000000-0000-0000-0000-000000000101'
             and '30000000-0000-0000-0000-000000000194';
